#include <bits/stdc++.h>
using namespace std;
#include "atcoder/modint.hpp"
using mint = atcoder::modint998244353;
int main() {
  cin.tie(0)->sync_with_stdio(0);
  int T;
  cin >> T;
  while (T--) {
    int N, M;
    cin >> N >> M;
    vector<int> A(N), r(N + 1);
    for (int i = 0; i < N; i++) cin >> A[i], r[i + 1] = r[i] + A[i];
    int K = r[N];
    vector m(K, vector<mint>(K));
    mt19937_64 rng(58);
    for (int _ = 0; _ < M; _++) {
      int u, v;
      cin >> u >> v;
      --u, --v;
      vector<mint> a(A[u]), b(A[v]);
      for (auto& x : a) x = rng();
      for (auto& x : b) x = rng();
      for (int i = 0; i < A[u]; i++) {
        for (int j = 0; j < A[v]; j++) {
          m[r[u] + i][r[v] + j] += a[i] * b[j];
          m[r[v] + j][r[u] + i] -= a[i] * b[j];
        }
      }
    }
    vector<pair<vector<mint>, int>> basis;
    for (auto& v : m) {
      for (auto& [w, top] : basis) {
        if (v[top] != 0) {
          mint c = v[top] / w[top];
          for (int i = 0; i < K; i++) v[i] -= w[i] * c;
        }
      }
      int top = 0;
      while (top < K and v[top] == 0) top++;
      if (top != K) basis.emplace_back(v, top);
    }
    cout << basis.size() / 2 << "\n";
  }
}
